changeSet.sql:
SET QUOTED_IDENTIFIER ON;
UPDATE app.Permissions SET Name = N'View others'' leave', Description = N'View the staff leave calendar for other people in this workspace.', UpdatedAt = SYSUTCDATETIME() WHERE Code = N'LEAVE_READ';
UPDATE app.Permissions SET Name = N'Apply own leave', Description = N'Submit and cancel your own staff leave requests and see them on the calendar.', UpdatedAt = SYSUTCDATETIME() WHERE Code = N'LEAVE_APPLY';
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r JOIN app.Permissions p ON p.Code = N'LEAVE_APPLY' WHERE r.TenantId IS NULL AND r.Name IN (N'SuperAdmin', N'GymOwner', N'BusinessAdmin', N'GymManager', N'Trainer', N'Receptionist', N'Accountant') AND NOT EXISTS (SELECT 1 FROM app.RolePermissions rp WHERE rp.RoleId = r.Id AND rp.PermissionId = p.Id);

rollback.sql:
UPDATE app.Permissions SET Name = N'Read staff leave', Description = N'View staff leave calendar and request details.', UpdatedAt = SYSUTCDATETIME() WHERE Code = N'LEAVE_READ';
UPDATE app.Permissions SET Name = N'Apply leave', Description = N'Submit and cancel own staff leave requests.', UpdatedAt = SYSUTCDATETIME() WHERE Code = N'LEAVE_APPLY';
DELETE rp FROM app.RolePermissions rp INNER JOIN app.Roles r ON r.Id = rp.RoleId INNER JOIN app.Permissions p ON p.Id = rp.PermissionId WHERE p.Code = N'LEAVE_APPLY' AND r.TenantId IS NULL AND r.Name IN (N'BusinessAdmin', N'Accountant');
